public class Main {
    public static void main(String[] args) {
        System.out.println(42);
    }
}

#include <iostream>
int main() {
    int n; std::cin >> n;
    long long total = 0;
    for (int i = 0; i < n; ++i) total += i % 97;
    std::cout << total << "\n";
}

#include <iostream>
#include <vector>
int main() {
    int n; std::cin >> n;
    std::vector<int> values(n);
    for (int i = 0; i < n; ++i) values[i] = i;
    long long total = 0;
    for (int value : values) total += value;
    std::cout << total << "\n";
}
